function directionalKoreanRoute(route,directionId){
  const direction=(route?.directions||[]).find(item=>item.id===directionId);
  if(!direction)throw new Error(`${route?.id||'route'}: missing ${directionId} direction`);
  if(direction.geometryStatus!=='ready'||direction.geometry?.length<2||direction.stops?.length<2)throw new Error(`${route.id}/${directionId}: verified directional geometry is unavailable`);
  return{...route,id:`${route.id}@${directionId}`,stations:direction.stops.map(station=>({...station})),geometry:copyGeometry(direction.geometry),directedSegments:(direction.directedSegments||[]).map(segment=>({...segment,geometry:copyGeometry(segment.geometry)})),geometryReady:true,geometryStatus:'ready',selectedDirectionId:directionId};
}

function koreanFamilyServiceChoices(passengerLineId){
  const definitions=koreanFamilyServices[String(passengerLineId)]||[],choices=[];
  for(const definition of definitions)for(const direction of ['forward','reverse']){
    const parts=definition.directions[direction];if(!parts?.length)continue;
    choices.push({kind:'koreanFamilyService',id:`korean-family:${definition.id}:${direction}`,patternId:definition.id,patternName:definition.names,direction,originId:`${definition.id}:${direction}:origin`,destinationId:`${definition.id}:${direction}:destination`,originNames:{ko:direction==='forward'?definition.names.ko.split(' ↔ ')[0]:definition.names.ko.split(' ↔ ')[1].replace(/\s+\([^)]*\)$/,'')},destinationNames:{ko:direction==='forward'?definition.names.ko.split(' ↔ ')[1].replace(/\s+\([^)]*\)$/,''):definition.names.ko.split(' ↔ ')[0]}})
  }
  return choices;
}

function resolveKoreanFamilyService(choice,getRoute){
  const definition=Object.values(koreanFamilyServices).flat().find(item=>item.id===choice?.patternId);
  const configs=definition?.directions?.[choice?.direction||'forward'];
  if(!definition||!configs?.length)throw new Error('대한민국 운행계통 정의를 찾을 수 없습니다.');
  const directionalRoutes=new Map,routeSegments=configs.map(config=>{
    const source=getRoute(config.routeId);if(!source)throw new Error(`${config.routeId}: 물리 노선 데이터를 찾을 수 없습니다.`);
    const directional=directionalKoreanRoute(source,config.directionId),routeId=directional.id;directionalRoutes.set(routeId,directional);
    return{routeId,startStationJa:config.startStationJa,endStationJa:config.endStationJa};
  });
  const spec={id:`${definition.id}-${choice.direction||'forward'}`,nameJa:definition.names.ko,nameKo:definition.names.ko,nameEn:definition.names.en,routeSegments,boundarySnapToleranceKm:.25};
  const route=buildThroughServiceRoute(spec,id=>directionalRoutes.get(id));
  if(definition.stopStationNames?.length){
    const wanted=new Set(definition.stopStationNames);
    route.stations=route.stations.filter(station=>wanted.has(station.ko));
    if(route.stations.length<2)throw new Error('급행 정차역 데이터가 부족합니다.');
  }
  // Make playable segment geometry for ALL Korean through-service choices, not
  // just expresses. A service crossing two physical lines must not retain the
  // first physical line's directedSegments or fall back to a straight line.
  route.directedSegments=route.stations.slice(0,-1).map((from,i)=>{
    const to=route.stations[i+1],a=from.geometryIndex,b=to.geometryIndex;
    if(!Number.isInteger(a)||!Number.isInteger(b)||b<=a||b>=route.geometry.length)
      throw new Error('1호선 운행계통 선형 누락: '+from.ko+' → '+to.ko);
    const points=copyGeometry(route.geometry.slice(a,b+1));
    if(points.length<2)throw new Error('1호선 역간 실제 선로가 없습니다: '+from.ko+' → '+to.ko);
    return {fromStationId:from.id,toStationId:to.id,geometry:points,source:'verified physical rail geometry (OSM segments)',geometryStatus:'ready',verified:true};
  });
  const service={id:definition.id,nameJa:definition.names.ko,nameKo:definition.names.ko,nameEn:definition.names.en,stops:route.stations.map(station=>station.id)};
  return{route:{...route,id:`korean-family-${definition.id}-${choice.direction||'forward'}`,countryId:'kr',line:{...(route.line||{}),ko:choice.patternId?.startsWith('kr-line1-')?'수도권 전철 1호선':'수도권 전철 5호선',ja:choice.patternId?.startsWith('kr-line1-')?'수도권 전철 1호선':'수도권 전철 5호선',en:choice.patternId?.startsWith('kr-line1-')?'Seoul Metropolitan Subway Line 1':'Seoul Metropolitan Subway Line 5'},passengerLineName:choice.patternId?.startsWith('kr-line1-')?'수도권 전철 1호선':'수도권 전철 5호선',geometryReady:true,geometryStatus:'ready',services:[service]},service,direction:'forward',travelDirectionId:choice.direction||'forward',pattern:{id:definition.id,names:definition.names},trainType:null,destinationStationId:route.stations.at(-1)?.id||null,trainTypeContexts:[]};
}

function buildBranchRoute(branch,source,contextRoute=source){
  if(!branch||!source||!contextRoute)throw new Error('Missing branch or parent route');
  const sourceMap=new Map((source.stations||[]).map(station=>[stationKey(station),station])),stations=branch.stationSequence.map(id=>sourceMap.get(String(id)));
  if(stations.some(station=>!station))throw new Error(`${branch.id}: branch station is missing from ${source.id}`);
  // Prefer a verified branch overlay when one is supplied. Otherwise reuse the
  // canonical physical branch's original track vertices (never draw a straight connector).
  const physicalReady=source.geometryReady===true
    && Array.isArray(source.geometry)&&source.geometry.length>=2
    && Array.isArray(source.directedSegments)
    && source.directedSegments.length===branch.stationSequence.length-1
    && source.directedSegments.every((segment,index)=>
      String(segment.fromStationId)===String(branch.stationSequence[index])
      && String(segment.toStationId)===String(branch.stationSequence[index+1])
      && Array.isArray(segment.geometry)&&segment.geometry.length>=2);
  const geometryData=branch.geometryData?.geometry?.length
    ? branch.geometryData
    : physicalReady?{geometry:source.geometry,directedSegments:source.directedSegments,geometryStatus:'ready'}:null;
  if(!geometryData?.geometry?.length||geometryData.geometryStatus!=='ready')
    throw new Error(`${branch.id}: verified branch geometry is unavailable`);
  const geometry=[],directedSegments=[],resolvedStations=[];
  for(let index=0;index<geometryData.directedSegments.length;index++){
    const part=copyGeometry(geometryData.directedSegments[index].geometry);if(geometry.length&&part.length&&geometry.at(-1)[0]===part[0][0]&&geometry.at(-1)[1]===part[0][1])part.shift();
    const from=stations[index],to=stations[index+1],fromCode=branch.stationCodes?.[stationKey(from)]||from.officialCode||'';resolvedStations[index]={...from,officialCode:fromCode,stationCode:fromCode,hasOfficialStationCode:!!fromCode,geometryIndex:Math.max(0,geometry.length-1),segment:contextOf(contextRoute)};geometry.push(...part);
    directedSegments.push({fromStationId:stationKey(from),toStationId:stationKey(to),geometry:copyGeometry(geometryData.directedSegments[index].geometry),source:geometryData.directedSegments[index].source,endpointMismatch:false})
  }
  const terminal=stations.at(-1),terminalCode=branch.stationCodes?.[stationKey(terminal)]||terminal.officialCode||'';resolvedStations[stations.length-1]={...terminal,officialCode:terminalCode,stationCode:terminalCode,hasOfficialStationCode:!!terminalCode,geometryIndex:Math.max(0,geometry.length-1),segment:contextOf(contextRoute)};
  return{...contextRoute,id:contextRoute.id,dataKind:'branch',physicalBranchRouteId:source.id,parentLineId:branch.parentLineId,branch,line:contextRoute.line,stations:resolvedStations,geometry,directedSegments,geometryReady:true,loop:false,coverage:'verified-osm-branch'}
}

function combineRouteParts(parts,identity){
  const stations=[],geometry=[],segments=[];
  for(const part of parts){
    if(!part?.stations?.length||!part?.geometry?.length)throw new Error(`${identity.id}: incomplete branch part`);
    if(stations.length&&!sameStation(stations.at(-1),part.stations[0]))throw new Error(`${identity.id}: disconnected branch junction`);
    if(geometry.length){
      const gapKm=pointDistanceKm(geometry.at(-1),part.geometry[0]);
      if(gapKm>.25)throw new Error(`${identity.id}: branch geometry gap (${gapKm.toFixed(3)} km)`);
    }
    const sharedBoundary=stations.length>0;
    let offset=geometry.length;
    const partGeometry=copyGeometry(part.geometry);
    if(sharedBoundary&&Math.hypot(geometry.at(-1)[0]-partGeometry[0][0],geometry.at(-1)[1]-partGeometry[0][1])<.002){
      offset--;partGeometry[0]=[...geometry.at(-1)];geometry.push(...partGeometry.slice(1));
    }else geometry.push(...partGeometry);
    const context=contextOf(part),segmentStart=Math.max(0,stations.length-1);
    for(let index=0;index<part.stations.length;index++){
      const station=part.stations[index];
      if(index===0&&sharedBoundary){
        // The branch's station-number context wins at a shared junction only
        // when it is the target; the caller orders the parts in travel order.
        stations[stations.length-1]={...station,geometryIndex:stations.at(-1).geometryIndex,segment:context};
        continue;
      }
      stations.push({...station,geometryIndex:(station.geometryIndex??0)+offset,segment:context});
    }
    segments.push({...context,fromStation:segmentStart,toStation:stations.length-1});
  }
  return{...parts[0],...identity,stations,geometry,segments,geometryReady:true,loop:false};
}

function buildBranchServiceRoute(pattern,baseRoute,getRoute){
  const branch=branchFor(pattern.branchId),branchSource=getRoute(branch?.legacyRouteId||branch?.routeId);
  if(!branchSource)throw new Error(`${pattern.id}: legacy branch geometry source is unavailable`);
  const branchRoute=buildBranchRoute(branch,branchSource,baseRoute),direction=pattern.directionId||'forward',junction=branch.junctionStationId;
  const branchPart=direction==='reverse'
    ?prepareThroughPart(branchRoute,{direction:'reverse',startStationId:pattern.originStationId,endStationId:junction})
    :prepareThroughPart(branchRoute,{direction:'forward',startStationId:junction,endStationId:pattern.destinationStationId});
  const needsMain=direction==='reverse'?pattern.destinationStationId!==junction:pattern.originStationId!==junction;
  const mainPart=!needsMain?null:direction==='reverse'
    ?prepareThroughPart(baseRoute,{direction:'reverse',startStationId:junction,endStationId:pattern.destinationStationId})
    :prepareThroughPart(baseRoute,{direction:'forward',startStationId:pattern.originStationId,endStationId:junction});
  const route=combineRouteParts(direction==='reverse'?[branchPart,...(mainPart?[mainPart]:[])]:[...(mainPart?[mainPart]:[]),branchPart],{
    id:`branch-service-${branch.id}`,
    dataKind:'branchServiceJourney',
    parentLineId:baseRoute.id,
    branch,
    line:baseRoute.line,
    operator:baseRoute.operator,
    operatorId:baseRoute.operatorId
  });
  const expected=(pattern.stationSequence||[]).map(String),actual=route.stations.map(stationKey);
  if(expected.length&&JSON.stringify(expected)!==JSON.stringify(actual))throw new Error(`${pattern.id}: resolved branch station sequence does not match the canonical pattern`);
  return route;
}

function resolveServiceSelection({baseRoute,servicePatternId,directionId='forward',legacyServiceId='local',getRoute}){
  const pattern=servicePatternFor(servicePatternId);
  if(!pattern){const service=baseRoute.services?.find(item=>item.id===legacyServiceId)||baseRoute.services?.[0];return{route:baseRoute,service,direction:directionId,pattern:null,trainType:null,destinationStationId:null}}
  if(pattern.baseRouteId!==baseRoute.id)throw new Error(`${pattern.id}: pattern does not belong to ${baseRoute.id}`);
  if(pattern.status&&pattern.status!=='active')throw new Error(`${pattern.id}: ${pattern.status}`);
  let route=baseRoute;
  if(pattern.throughServiceId){const spec=(globalThis.TRT_RAIL_SYSTEM?.throughServices||[]).find(item=>item.id===pattern.throughServiceId);route=buildThroughServiceRoute(spec,getRoute,pattern.directionId||directionId)}
  else if(pattern.branchId)route=buildBranchServiceRoute(pattern,baseRoute,getRoute);
  else route=prepareThroughPart(route,{direction:pattern.directionId||directionId,startStationId:pattern.originStationId,endStationId:pattern.destinationStationId});
  const routeIdsSet=new Set(route.stations.map(stationKey)),stops=(pattern.stopStationIds?.length?pattern.stopStationIds:route.stations.map(stationKey)).map(String);
  for(const id of stops)if(!routeIdsSet.has(id))throw new Error(`${pattern.id}: stop ${id} is outside the resolved route`);
  const service={id:pattern.id,nameJa:pattern.names.ja,nameKo:pattern.names.ko,nameEn:pattern.names.en,stops,trainTypeId:pattern.trainTypeId,destinationStationId:pattern.destinationStationId,throughServiceId:pattern.throughServiceId||null};
  // A directional through route is already assembled in travel order. Passing
  // "reverse" to the game would reverse it a second time.
  const resolvedDirection='forward';
  return{route:{...route,services:[service]},service,direction:resolvedDirection,travelDirectionId:pattern.directionId||directionId,pattern,trainType:trainTypeFor(pattern.trainTypeId),destinationStationId:pattern.destinationStationId}
}

function resolveServiceJourney({baseRoute,journeyId,originStationId,destinationStationId,trainTypeId,getRoute}){
  const journeys=serviceJourneysForRoute(baseRoute.id),journey=journeys.find(item=>item.id===journeyId)||journeys.find(item=>item.originStationId===originStationId&&item.destinationStationId===destinationStationId&&item.trainTypeId===trainTypeId);
  if(!journey)throw new Error('실제로 운행하는 출발지·종착지·열차종별 조합이 아닙니다.');
  const resolved=resolveServiceSelection({baseRoute,servicePatternId:journey.servicePatternId,directionId:journey.directionId,getRoute});
  const segmentTypeMap=new Map((resolved.pattern.segmentTrainTypeContexts||[]).map(item=>[item.routeId,item.trainTypeId]));
  const trainTypeContexts=(resolved.route.segments||[{id:resolved.route.id,fromStation:0,toStation:resolved.route.stations.length-1}]).map(segment=>({
    routeId:segment.id,fromStation:segment.fromStation??0,toStation:segment.toStation??resolved.route.stations.length-1,trainTypeId:segmentTypeMap.get(segment.id)||journey.trainTypeId,
    trainType:trainTypeFor(segmentTypeMap.get(segment.id)||journey.trainTypeId)
  }));
  const route={...resolved.route,serviceJourney:{...journey},trainTypeContexts};
  return{...resolved,route,journey:{...journey},journeyId:journey.id,trainTypeContexts};
}


