// Keep the rail system lazy, but hydrate the stations of an officially
// connected differently named interchange before building the free-drive graph.
async function hydrateJapaneseNamedTransferConnections(route){
  if(route?.countryId!=='jp')return;
  // The generated nationwide graph covers shared master IDs, spatially
  // aligned independently named IDs and the verified alias groups. The
  // previous name-only catalog remains a fallback for pre-build browsers.
  const nationalNeighbors=globalThis.TRT_JAPAN_LITE_INDEX?.transferNeighbors;
  const neighborIds=new Set(nationalNeighbors?.[route.id]||[]);
  const names=new Set(japaneseNamedTransferNamesForRoute(route));
  // GitHub Pages can temporarily serve a pre-regeneration lite index without
  // nationwide transferNeighbors. Fall back to station-name discovery across
  // ALL regions, including a line's unmodified master station names. The
  // free-drive graph then checks shared IDs or locally verified interchange
  // evidence; a name match by itself never authorizes a transfer.
  if(!nationalNeighbors||!Object.keys(nationalNeighbors).length){
    for(const stop of route.stations||[]){
      if(stop.ja)names.add(stop.ja);
      if(stop.canonicalStationNames?.ja)names.add(stop.canonicalStationNames.ja);
    }
  }
  if(!neighborIds.size&&!names.size)return;
  const candidates=builtin.filter(line=>
    line.countryId==='jp'&&line.id!==route.id&&line.lazy
    &&isRouteVisible(line)
    &&(neighborIds.has(line.id)||(line.searchStations||[]).some(name=>names.has(name))));
  for(let offset=0;offset<candidates.length;offset+=6){
    const batch=candidates.slice(offset,offset+6);
    const hydrated=await Promise.allSettled(batch.map(line=>hydrateRailLine(line)));
    hydrated.forEach((entry,index)=>{
      const line=batch[index];
      if(entry.status==='rejected'){
        console.warn('Named interchange counterpart unavailable:',line.id,entry.reason);
        return;
      }
      const resolved=railDataRepository.resolveRoute(entry.value);
      const found=builtin.findIndex(item=>item.id===line.id);
      if(found>=0)builtin[found]=resolved;
    });
  }
  if(candidates.length)refreshRoutes();
}
async function startFreeDrive(route){if(isKoreanResearch(route))return toast('연구용 경로는 확인된 정차 순서로만 주행할 수 있습니다.');
  if(!route)return toast('자유주행을 시작할 노선을 선택해 주세요.');
  if(koreanRouteUnavailableReason(route))return toast('자유주행 불가: '+koreanRouteUnavailableReason(route));
  let target=route;
  if(target.lazy){const ok=await chooseRoute(target.id);if(!ok)return;target=selected}
  if(koreanRouteUnavailableReason(target))return toast('자유주행 불가: '+koreanRouteUnavailableReason(target));
  if(!target?.stations?.length)return toast('자유주행에 사용할 역 데이터가 없는 노선입니다.');
  if(target.countryId==='jp')await hydrateJapaneseNamedTransferConnections(target);
  if(target.countryId==='kr'){
    const counterpartIds=KR_APP_TRANSFER_PAIRS.flatMap(t=>t.routeIds.includes(target.id)?t.routeIds:[]).filter(id=>id!==target.id);
    for(const id of new Set(counterpartIds)){
      const other=builtin.find(line=>line.id===id);
      if(!other?.lazy)continue;
      try{const hydrated=railDataRepository.resolveRoute(await hydrateRailLine(other)),pos=builtin.findIndex(line=>line.id===id);if(pos>=0)builtin[pos]=hydrated;}catch(error){console.warn('Korean transfer counterpart unavailable:',id,error)}
    }
    refreshRoutes();
  }
  freeDrive?.setNetwork(freeDriveNetworkRoutes());
  // allRoutes() clones Japan station objects for localized names. The transfer
  // graph attaches its route-specific transfer keys to its own station copies;
  // starting from an older selected copy would miss those keys entirely.
  const networkStart=freeDrive?.routes?.find(line=>line.id===target.id)||target;
  const chosenStart=Number($('#free-drive-start-station')?.value);
  const startIndex=Number.isInteger(chosenStart)&&chosenStart>=0&&chosenStart<networkStart.stations.length?chosenStart:0;
  if(!freeDrive?.start(networkStart,startIndex))return toast('자유주행을 시작하지 못했습니다.');
  const state=freeDrive.snapshot();if(!state||!game.startFreeDrive(state))return toast('자유주행 화면을 준비하지 못했습니다.');
  freeDriveTabIndex=0;renderGameFreeDriveOptions(state);go('game');
}
